package com.bank.deploy.model;

// Represents one Kubernetes pod with a version and readiness state.
public class Pod {
    private final String version;
    private boolean ready;

    public Pod(String version) {
        this.version = version;
        this.ready = false; // pods start not-ready until the readiness probe passes
    }

    public void markReady() { this.ready = true; }
    public boolean isReady() { return ready; }
    public String getVersion() { return version; }
}
