package com.bank.deploy.strategy;

import com.bank.deploy.model.Pod;
import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

// Replaces pods one at a time, keeping the service available throughout.
public class RollingUpdateStrategy implements DeploymentStrategy {
    private static final Logger log = Logger.getLogger(RollingUpdateStrategy.class.getName());

    @Override
    public List<Pod> deploy(List<Pod> current, String newVersion, int desired) {
        List<Pod> pods = new ArrayList<>(current);
        for (int i = 0; i < desired; i++) {
            // Surge: add a new pod first (maxUnavailable=0 means never drop below desired).
            Pod fresh = new Pod(newVersion);
            pods.add(fresh);
            log.info(() -> "surged new pod " + newVersion + " (starting up)");
            fresh.markReady(); // readiness probe passes
            reportAvailability(pods);
            // Only now remove one old pod.
            pods.stream().filter(p -> !p.getVersion().equals(newVersion))
                .findFirst().ifPresent(old -> {
                    pods.remove(old);
                    log.info("retired one old pod");
                });
            reportAvailability(pods);
        }
        return pods;
    }

    private void reportAvailability(List<Pod> pods) {
        long ready = pods.stream().filter(Pod::isReady).count();
        log.info(() -> "serving pods ready = " + ready
                + " | versions live = " + pods.stream().map(Pod::getVersion).distinct().toList());
    }

    @Override public String name() { return "RollingUpdate"; }
}
