package com.bank.deploy.strategy;

import com.bank.deploy.model.Pod;
import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

// Terminates ALL old pods first, then starts the new ones. Downtime in between.
public class RecreateStrategy implements DeploymentStrategy {
    private static final Logger log = Logger.getLogger(RecreateStrategy.class.getName());

    @Override
    public List<Pod> deploy(List<Pod> current, String newVersion, int desired) {
        log.warning("terminating ALL old pods -> DOWNTIME WINDOW BEGINS");
        List<Pod> pods = new ArrayList<>(); // zero pods serving now
        log.warning(() -> "serving pods ready = 0 | versions live = [] (service DOWN)");

        for (int i = 0; i < desired; i++) {
            Pod fresh = new Pod(newVersion);
            fresh.markReady();
            pods.add(fresh);
        }
        log.info("new pods ready -> DOWNTIME WINDOW ENDS");
        log.info(() -> "serving pods ready = " + pods.size()
                + " | versions live = [" + newVersion + "]");
        return pods;
    }

    @Override public String name() { return "Recreate"; }
}
