package com.bank.deploy.service;

import com.bank.deploy.model.Pod;
import com.bank.deploy.strategy.DeploymentStrategy;
import java.util.List;
import java.util.logging.Logger;

// Runs a chosen strategy. Does not care which one — depends on the interface.
public class Deployer {
    private static final Logger log = Logger.getLogger(Deployer.class.getName());

    public List<Pod> rollout(DeploymentStrategy strategy, List<Pod> current,
                             String newVersion, int desired) {
        log.info(() -> "=== deploying with " + strategy.name() + " ===");
        return strategy.deploy(current, newVersion, desired);
    }
}
