package com.bank.deploy;

import com.bank.deploy.model.Pod;
import com.bank.deploy.service.Deployer;
import com.bank.deploy.strategy.RecreateStrategy;
import com.bank.deploy.strategy.RollingUpdateStrategy;
import java.util.ArrayList;
import java.util.List;

public class DeployDemo {
    public static void main(String[] args) {
        Deployer deployer = new Deployer();

        // Transfer API: 4 pods on v2.3.0, roll to v2.4.0 with zero downtime.
        List<Pod> transferPods = new ArrayList<>();
        for (int i = 0; i < 4; i++) { Pod p = new Pod("2.3.0"); p.markReady(); transferPods.add(p); }
        deployer.rollout(new RollingUpdateStrategy(), transferPods, "2.4.0", 4);

        // Settlement Scheduler: 1 singleton pod, must not overlap.
        List<Pod> schedulerPods = new ArrayList<>();
        Pod s = new Pod("2.3.0"); s.markReady(); schedulerPods.add(s);
        deployer.rollout(new RecreateStrategy(), schedulerPods, "2.4.0", 1);
    }
}
